"use client"

import * as React from "react"
import { ArrowLeft } from "lucide-react"
import { AnimatePresence, motion, useReducedMotion } from "motion/react"

import {
  AfterglowMark,
  Field,
  ProviderButton,
  SubmitLabel,
  checkEmail,
  useSubmit,
  type Provider,
} from "@/components/ui/auth-parts"
import { LiquidGlass } from "@/components/ui/liquid-glass"
import { LiquidMetal } from "@/components/ui/liquid-metal"
import { cn } from "@/lib/utils"

type Story = { company: string; quote: string; person: string }

const defaultStories: Story[] = [
  {
    company: "Northwind",
    quote: "We rebuilt onboarding in a week, and sign-ups went up 38%.",
    person: "Lena Park, Head of Growth",
  },
  {
    company: "Halcyon",
    quote: "Our team ships the same polish without a single design review.",
    person: "Omar Reyes, CTO",
  },
  {
    company: "Quill",
    quote: "It feels like the product finally matches the brand.",
    person: "Iris Novak, Founder",
  },
]

const STORY_MS = 6000

type AuthSplitProps = {
  /** sends the magic link; throw to show an error under the field */
  onSubmit?: (values: { email: string }) => Promise<void> | void
  onProvider?: (provider: Provider) => void
  stories?: Story[]
  className?: string
}

const primary =
  "inline-flex h-10 w-full cursor-pointer items-center justify-center rounded-[10px] bg-foreground text-[13px] font-medium text-background shadow-[inset_0_1px_0_oklch(1_0_0/12%),0_1px_2px_oklch(0_0_0/20%)] transition-[background-color,scale] duration-150 ease-out outline-none hover:bg-foreground/90 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-foreground/40 active:scale-[0.98]"

const secondary = "h-10 rounded-[10px] bg-transparent text-[13px] hover:bg-muted/60"

// email first on the left; on the right, customer stories in glass over graphite silk
export function AuthSplit({ onSubmit, onProvider, stories = defaultStories, className }: AuthSplitProps) {
  const reduceMotion = useReducedMotion()
  const [email, setEmail] = React.useState("")
  const [emailError, setEmailError] = React.useState<string>()
  const { status, error, run, reset } = useSubmit(onSubmit)

  function handleSubmit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault()
    const next = checkEmail(email)
    setEmailError(next)
    if (!next) run({ email: email.trim() })
  }

  const swap = {
    initial: reduceMotion ? { opacity: 0 } : { opacity: 0, y: 8 },
    animate: { opacity: 1, y: 0 },
    exit: { opacity: 0, transition: { duration: 0.12 } },
    transition: { duration: 0.25, ease: [0.22, 1, 0.36, 1] as const },
  }

  return (
    <div className={cn("grid min-h-[44rem] w-full bg-background text-foreground lg:grid-cols-2", className)}>
      <div className="flex flex-col items-center justify-between gap-10 px-6 py-10">
        <span className="inline-flex items-center gap-2 text-[15px] font-medium tracking-[-0.01em] [&_svg]:size-5">
          <AfterglowMark />
          Afterglow
        </span>

        <div className="w-full max-w-[20rem]">
          <AnimatePresence mode="wait" initial={false}>
            {status === "done" ? (
              <motion.div key="sent" className="flex flex-col items-center text-center" {...swap}>
                <h1 className="text-[22px] font-medium tracking-[-0.02em]">Check your email</h1>
                <p className="mt-2 text-[13px] leading-relaxed text-muted-foreground">
                  We sent a sign-in link to <span className="text-foreground">{email.trim()}</span>.
                </p>
                <div className="mt-7 grid w-full grid-cols-2 gap-2">
                  <a href="https://mail.google.com" target="_blank" rel="noreferrer" className={cn(primary, "bg-muted text-foreground shadow-none hover:bg-muted/70")}>
                    Open Gmail
                  </a>
                  <a href="https://outlook.live.com" target="_blank" rel="noreferrer" className={cn(primary, "bg-muted text-foreground shadow-none hover:bg-muted/70")}>
                    Open Outlook
                  </a>
                </div>
                <button
                  type="button"
                  onClick={reset}
                  className="mt-6 inline-flex cursor-pointer items-center gap-1.5 rounded text-[13px] text-muted-foreground transition-colors duration-150 outline-none hover:text-foreground focus-visible:outline-2 focus-visible:outline-foreground/40"
                >
                  <ArrowLeft className="size-3.5" />
                  Use a different email
                </button>
              </motion.div>
            ) : (
              <motion.div key="form" className="flex flex-col" {...swap}>
                <h1 className="text-center text-[22px] font-medium tracking-[-0.02em]">Log in to Afterglow</h1>
                <form noValidate onSubmit={handleSubmit} className="mt-8 flex flex-col gap-3">
                  <Field
                    label="Work email"
                    name="email"
                    type="email"
                    autoComplete="email"
                    placeholder="you@company.com"
                    value={email}
                    onChange={(event) => setEmail(event.target.value)}
                    error={emailError ?? error}
                    boxClassName="rounded-[10px] bg-background focus-within:border-foreground/30 focus-within:ring-4 focus-within:ring-foreground/[0.06]"
                    labelClassName="text-[13px]"
                  />
                  <button type="submit" disabled={status === "loading"} className={primary}>
                    <SubmitLabel loading={status === "loading"}>Continue with email</SubmitLabel>
                  </button>
                </form>
                <div className="my-6 flex items-center gap-3 text-xs text-muted-foreground">
                  <span className="h-px flex-1 bg-border" />
                  or
                  <span className="h-px flex-1 bg-border" />
                </div>
                <div className="flex flex-col gap-2">
                  <ProviderButton provider="google" className={secondary} onClick={() => onProvider?.("google")} />
                  <ProviderButton provider="github" className={secondary} onClick={() => onProvider?.("github")} />
                  <ProviderButton provider="sso" verb="Continue with SAML" className={secondary} onClick={() => onProvider?.("sso")} />
                </div>
                <p className="mt-7 text-center text-[13px] text-muted-foreground">
                  Don&rsquo;t have an account?{" "}
                  <a href="#" className="text-foreground transition-opacity duration-150 hover:opacity-70">
                    Sign up
                  </a>
                </p>
              </motion.div>
            )}
          </AnimatePresence>
        </div>

        <p className="text-center text-xs text-muted-foreground">
          By continuing, you agree to our{" "}
          <a href="#" className="underline decoration-border underline-offset-2 hover:text-foreground">Terms</a> and{" "}
          <a href="#" className="underline decoration-border underline-offset-2 hover:text-foreground">Privacy Policy</a>.
        </p>
      </div>

      <StoryPanel stories={stories} />
    </div>
  )
}

function StoryPanel({ stories }: { stories: Story[] }) {
  const reduceMotion = useReducedMotion()
  const [index, setIndex] = React.useState(0)
  const [paused, setPaused] = React.useState(false)
  const story = stories[index]

  return (
    <div className="dark relative isolate m-3 hidden overflow-hidden rounded-[22px] bg-[oklch(0.1_0.002_285)] text-white lg:block">
      <LiquidMetal pattern="silk" softness={0.7} brightness={-0.22} scale={0.7} tint={[1, 1, 1]} speed={0.4} quality={0.6} />
      <div aria-hidden className="absolute inset-0 bg-[linear-gradient(180deg,transparent_45%,oklch(0_0_0/55%))]" />

      <div className="absolute inset-x-6 bottom-6">
        <LiquidGlass
          className="rounded-[22px] p-6"
          bezel={22}
          frost={6}
          tint="oklch(0.12 0.003 285 / 45%)"
          onPointerEnter={() => setPaused(true)}
          onPointerLeave={() => setPaused(false)}
        >
          <AnimatePresence mode="wait" initial={false}>
            <motion.figure
              key={story.company}
              initial={reduceMotion ? { opacity: 0 } : { opacity: 0, y: 6 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, transition: { duration: 0.12 } }}
              transition={{ duration: 0.3, ease: "easeOut" }}
            >
              <p className="text-xs font-medium tracking-[0.14em] text-white/55 uppercase">{story.company}</p>
              <blockquote className="mt-3 text-[17px] leading-snug font-medium tracking-[-0.01em] text-balance">
                &ldquo;{story.quote}&rdquo;
              </blockquote>
              <figcaption className="mt-3 text-[13px] text-white/55">{story.person}</figcaption>
            </motion.figure>
          </AnimatePresence>
          <div className="mt-5 flex gap-1.5">
            {stories.map((item, i) => (
              <button
                key={item.company}
                type="button"
                aria-label={`Show ${item.company}'s story`}
                aria-current={i === index}
                onClick={() => setIndex(i)}
                className="relative h-1 flex-1 cursor-pointer overflow-hidden rounded-full bg-white/20 outline-none focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-white/60"
              >
                {i < index && <span className="absolute inset-0 bg-white/90" />}
                {i === index && (
                  <Progress
                    key={index}
                    paused={paused}
                    still={!!reduceMotion}
                    onDone={() => setIndex((index + 1) % stories.length)}
                  />
                )}
              </button>
            ))}
          </div>
        </LiquidGlass>
      </div>
    </div>
  )
}

// fills over the story's time; pausing freezes it mid-way, and finishing moves on
function Progress({ paused, still, onDone }: { paused: boolean; still: boolean; onDone: () => void }) {
  const ref = React.useRef<HTMLSpanElement>(null)
  const animation = React.useRef<Animation | null>(null)
  // the latest onDone, read when the bar finishes
  const done = React.useRef(onDone)
  React.useEffect(() => {
    done.current = onDone
  })

  React.useEffect(() => {
    const node = ref.current
    if (!node) return
    // under reduced motion the timer never runs, so show the bar full
    if (still) {
      node.style.transform = "none"
      return
    }
    const fill = node.animate([{ transform: "scaleX(0)" }, { transform: "scaleX(1)" }], {
      duration: STORY_MS,
      easing: "linear",
      fill: "forwards",
    })
    fill.onfinish = () => done.current()
    animation.current = fill
    return () => fill.cancel()
  }, [still])

  React.useEffect(() => {
    if (paused) animation.current?.pause()
    else animation.current?.play()
  }, [paused])

  return <span ref={ref} className="absolute inset-0 origin-left bg-white/90" style={{ transform: "scaleX(0)" }} />
}

"use client"

import * as React from "react"
import { useReducedMotion } from "motion/react"

import { ringMask } from "@/lib/afterglow"
import { cn } from "@/lib/utils"

/*
 * Liquid metal: a slowly flowing metal surface, drawn by a small WebGL shader.
 * The surface is sine waves bent by other sine waves; each pixel reflects a
 * photo-studio backdrop (dark floor, bright horizon), which reads as metal.
 * Softness blurs that horizon, turning mirror chrome into brushed satin.
 *
 * Every piece on the page shares one WebGL context: it draws each piece in
 * turn and copies the frame into that piece's own canvas. Browsers cap live
 * contexts at about 16, so this keeps any number of pieces running.
 */

const VERTEX = `
attribute vec2 position;
varying vec2 vUv;
void main() {
  vUv = position * 0.5 + 0.5;
  gl_Position = vec4(position, 0.0, 1.0);
}`

const FRAGMENT = `
precision highp float;
varying vec2 vUv;
uniform vec2 uResolution;
uniform float uTime;
uniform vec3 uTint;
uniform float uBrightness;
uniform float uScale;
uniform float uSoftness;
uniform float uSilk;

// round ripples, like a pool of mercury
float liquid(vec2 p, float t) {
  vec2 q = p;
  q += 0.55 * vec2(sin(q.y * 1.3 + t * 1.1), sin(q.x * 1.1 - t * 0.9));
  q += 0.28 * vec2(sin(q.y * 2.3 - t * 0.7), sin(q.x * 2.1 + t * 1.3));
  return 0.5 * sin(q.x * 1.4 + t * 0.4) + 0.5 * sin(q.y * 1.7 - t * 0.3);
}

// long diagonal folds, like draped silk
float silk(vec2 p, float t) {
  vec2 d = normalize(vec2(1.0, 0.55));
  float u = dot(p, d);
  float v = dot(p, vec2(-d.y, d.x));
  float w = u + 0.45 * sin(v * 0.9 + t * 0.8) + 0.2 * sin(v * 2.1 - t * 0.6);
  return 0.65 * sin(w * 1.7 + t * 0.35) + 0.35 * sin(w * 3.1 - v * 0.4 - t * 0.25);
}

float height(vec2 p, float t) {
  return mix(liquid(p, t), silk(p, t), uSilk);
}

float studio(float y, float soft) {
  float edge = mix(0.03, 0.5, soft);
  float ground = 0.05 + 0.12 * smoothstep(-1.2, -0.15, y);
  float sky = 0.5 + 0.42 * smoothstep(0.05, 1.0, y);
  float v = mix(ground, sky, smoothstep(-edge, edge, y));
  v += mix(0.75, 0.28, soft) * exp(-pow((y - 0.03) * mix(26.0, 3.0, soft), 2.0));
  v += 0.2 * exp(-pow((y - 0.6) * 8.0, 2.0));
  return v;
}

void main() {
  vec2 p = (vUv - 0.5) * vec2(uResolution.x / uResolution.y, 1.0) * 2.2 * uScale;
  float t = uTime * 0.25;
  float e = 0.01;
  float h = height(p, t);
  float dx = (height(p + vec2(e, 0.0), t) - h) / e;
  float dy = (height(p + vec2(0.0, e), t) - h) / e;
  float k = mix(0.8, 0.32, uSoftness);
  vec3 n = normalize(vec3(-dx * k, -dy * k, 1.0));
  vec3 r = reflect(vec3(0.0, 0.0, -1.0), n);
  float y = r.y * 1.1 + p.y * 0.12 + 0.12 + uBrightness;
  float v = studio(y, uSoftness) + mix(0.3, 0.12, uSoftness) * pow(max(r.x, 0.0), 5.0);
  vec3 color = vec3(v);
  color = mix(color, color * uTint, 0.4 * smoothstep(0.35, 1.0, v));
  gl_FragColor = vec4(color, 1.0);
}`

// shown before the first frame, and wherever WebGL isn't available
const CHROME_FALLBACK =
  "conic-gradient(from 200deg at 35% 45%, #18181b, #e9e2da 14%, #2a2a2e 27%, #a29c95 41%, #141416 55%, #f3ece4 69%, #38383c 83%, #18181b)"
const SATIN_FALLBACK =
  "linear-gradient(155deg, #2a2a2e, #8d8984 40%, #d6d1cb 52%, #5a5a5e 75%, #1c1c1f)"

type Settings = {
  speed: number
  tint: [number, number, number]
  brightness: number
  scale: number
  softness: number
  silk: number
  maxAspect: number
  still: boolean
}

type Piece = {
  canvas: HTMLCanvasElement
  context: CanvasRenderingContext2D
  settings: Settings
  start: number
  visible: boolean
  painted: boolean
}

type Renderer = {
  canvas: HTMLCanvasElement
  gl: WebGLRenderingContext
  uniforms: Record<string, WebGLUniformLocation | null>
}

const pieces = new Set<Piece>()
let renderer: Renderer | null = null
let unavailable = false
let frame = 0

function createRenderer(): Renderer | null {
  const canvas = document.createElement("canvas")
  const gl = canvas.getContext("webgl", { antialias: false, alpha: false })
  if (!gl) return null
  const compile = (type: number, source: string) => {
    const shader = gl.createShader(type)!
    gl.shaderSource(shader, source)
    gl.compileShader(shader)
    return shader
  }
  const program = gl.createProgram()!
  gl.attachShader(program, compile(gl.VERTEX_SHADER, VERTEX))
  gl.attachShader(program, compile(gl.FRAGMENT_SHADER, FRAGMENT))
  gl.linkProgram(program)
  if (!gl.getProgramParameter(program, gl.LINK_STATUS)) return null
  gl.useProgram(program)
  // one triangle that covers the whole viewport
  gl.bindBuffer(gl.ARRAY_BUFFER, gl.createBuffer())
  gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 3, -1, -1, 3]), gl.STATIC_DRAW)
  const position = gl.getAttribLocation(program, "position")
  gl.enableVertexAttribArray(position)
  gl.vertexAttribPointer(position, 2, gl.FLOAT, false, 0, 0)
  const names = ["uResolution", "uTime", "uTint", "uBrightness", "uScale", "uSoftness", "uSilk"]
  const uniforms = Object.fromEntries(names.map((name) => [name, gl.getUniformLocation(program, name)]))

  canvas.addEventListener("webglcontextlost", (event) => {
    event.preventDefault()
    cancelAnimationFrame(frame)
    frame = 0
    renderer = null
    for (const piece of pieces) {
      piece.painted = false
      piece.canvas.style.opacity = "0"
    }
    // build a fresh context once the browser has recovered
    window.setTimeout(wake, 1000)
  })
  return { canvas, gl, uniforms }
}

function paint(piece: Piece, now: number) {
  const { canvas, gl, uniforms } = renderer!
  const { width, height } = piece.canvas
  // the shared canvas only grows, and each piece draws into its bottom-left corner
  if (canvas.width < width || canvas.height < height) {
    canvas.width = Math.max(canvas.width, width)
    canvas.height = Math.max(canvas.height, height)
  }
  const s = piece.settings
  gl.viewport(0, 0, width, height)
  gl.uniform2f(uniforms.uResolution, width, height)
  // under reduced motion, hold one pleasing frame
  gl.uniform1f(uniforms.uTime, s.still ? 3 : ((now - piece.start) / 1000) * s.speed + 3)
  gl.uniform3f(uniforms.uTint, ...s.tint)
  gl.uniform1f(uniforms.uBrightness, s.brightness)
  // past maxAspect, ripples stretch across wide shapes instead of repeating
  const aspect = width / height
  gl.uniform1f(uniforms.uScale, s.maxAspect && aspect > s.maxAspect ? (s.scale * s.maxAspect) / aspect : s.scale)
  gl.uniform1f(uniforms.uSoftness, s.softness)
  gl.uniform1f(uniforms.uSilk, s.silk)
  gl.drawArrays(gl.TRIANGLES, 0, 3)
  piece.context.drawImage(canvas, 0, canvas.height - height, width, height, 0, 0, width, height)
  piece.painted = true
  piece.canvas.style.opacity = "1"
}

function tick(now: number) {
  frame = 0
  if (!renderer) return
  let moving = false
  for (const piece of pieces) {
    if (!piece.visible || piece.canvas.width < 2) continue
    if (piece.settings.still && piece.painted) continue
    paint(piece, now)
    if (!piece.settings.still) moving = true
  }
  if (moving) frame = requestAnimationFrame(tick)
}

function wake() {
  if (frame || unavailable) return
  if (!renderer) {
    renderer = createRenderer()
    if (!renderer) {
      unavailable = true
      return
    }
  }
  frame = requestAnimationFrame(tick)
}

type LiquidMetalProps = React.ComponentProps<"div"> & {
  /** 1 is a slow drift */
  speed?: number
  /** warms or cools the highlights, as r, g, b from 0 to 1 */
  tint?: [number, number, number]
  /** 0.5 renders at half resolution, plenty for thin rims */
  quality?: number
  /** shifts the reflection toward the bright sky; 0.8 is mostly silver */
  brightness?: number
  /** below 1 makes the ripples broader, good for small or wide shapes */
  scale?: number
  /** 0 is mirror chrome, 1 is soft brushed satin */
  softness?: number
  /** "silk" lays the ripples out as long diagonal folds */
  pattern?: "liquid" | "silk"
  /** wider than this width-to-height ratio, ripples stretch instead of repeating */
  maxAspect?: number
}

function LiquidMetal({
  speed = 1,
  tint = [1, 0.82, 0.66],
  quality = 1,
  brightness = 0,
  scale = 1,
  softness = 0,
  pattern = "liquid",
  maxAspect = 0,
  className,
  style,
  ...props
}: LiquidMetalProps) {
  const reduceMotion = useReducedMotion()
  const rootRef = React.useRef<HTMLDivElement>(null)
  const [r, g, b] = tint

  React.useEffect(() => {
    const root = rootRef.current
    if (!root) return
    const canvas = document.createElement("canvas")
    canvas.className = "absolute inset-0 size-full opacity-0 transition-opacity duration-300"
    const context = canvas.getContext("2d", { alpha: false })
    if (!context) return
    root.appendChild(canvas)

    const piece: Piece = {
      canvas,
      context,
      settings: {
        speed,
        tint: [r, g, b],
        brightness,
        scale,
        softness,
        silk: pattern === "silk" ? 1 : 0,
        maxAspect,
        still: !!reduceMotion,
      },
      start: performance.now(),
      visible: false,
      painted: false,
    }
    pieces.add(piece)

    const visibility = new IntersectionObserver(([entry]) => {
      piece.visible = entry.isIntersecting
      if (piece.visible) wake()
    })
    visibility.observe(canvas)

    const sizing = new ResizeObserver(() => {
      const ratio = Math.min(window.devicePixelRatio || 1, 2) * quality
      canvas.width = Math.max(1, Math.round(canvas.clientWidth * ratio))
      canvas.height = Math.max(1, Math.round(canvas.clientHeight * ratio))
      // resizing clears the canvas, so paint again
      piece.painted = false
      wake()
    })
    sizing.observe(canvas)

    return () => {
      visibility.disconnect()
      sizing.disconnect()
      pieces.delete(piece)
      canvas.remove()
    }
  }, [b, brightness, g, maxAspect, pattern, quality, r, reduceMotion, scale, softness, speed])

  return (
    <div
      ref={rootRef}
      data-slot="liquid-metal"
      aria-hidden
      className={cn("pointer-events-none absolute inset-0 overflow-hidden rounded-[inherit]", className)}
      style={{ background: softness >= 0.5 ? SATIN_FALLBACK : CHROME_FALLBACK, ...style }}
      {...props}
    />
  )
}

type MetalRimProps = Omit<React.ComponentProps<"span">, "children"> & {
  /** thickness of the ring in px */
  width?: number
  brightness?: number
  quality?: number
}

/*
 * A hairline of chrome around its parent (give the parent a radius and
 * position). A steady edge, lit from above, sits under the moving metal; the
 * metal is screen-blended on top, so its dark patches never break the ring.
 */
function MetalRim({ width = 1, brightness = 0.35, quality = 0.6, className, style, ...props }: MetalRimProps) {
  return (
    <span
      aria-hidden
      data-slot="metal-rim"
      className={cn("pointer-events-none absolute inset-0 rounded-[inherit]", className)}
      style={{ ...ringMask, padding: width, ...style }}
      {...props}
    >
      <span className="absolute inset-0 rounded-[inherit] bg-[linear-gradient(180deg,oklch(0.78_0.01_80),oklch(0.36_0.004_285)_40%,oklch(0.3_0.004_285)_70%,oklch(0.55_0.006_80))]" />
      <LiquidMetal className="mix-blend-screen" quality={quality} brightness={brightness} maxAspect={3.2} />
    </span>
  )
}

export { LiquidMetal, MetalRim, type LiquidMetalProps, type MetalRimProps }

"use client"

import * as React from "react"
import {
  isMotionValue,
  motion,
  useMotionValue,
  useTransform,
  type MotionValue,
} from "motion/react"

import { ringMask } from "@/lib/afterglow"
import { cn } from "@/lib/utils"

/*
 * Liquid glass: a pane that bends whatever sits behind it, like Apple's
 * Liquid Glass. The rim is a curved lens, so content near the edges is
 * pulled inward, while the flat middle stays clear.
 *
 * Refraction is an SVG displacement map used as a backdrop-filter, which only
 * Chromium supports. Other browsers get a frosted fallback with the same rim.
 */

const SAMPLES = 128
const INDEX_OF_REFRACTION = 1.5

// convex squircle: flat in the middle, rounding off toward the rim
const surface = (x: number) => Math.pow(1 - Math.pow(1 - x, 4), 0.25)

// how far a straight-down ray is bent sideways at each point across the rim
function rimProfile(bezel: number) {
  const profile = new Float32Array(SAMPLES)
  for (let i = 0; i < SAMPLES; i++) {
    const x = i / (SAMPLES - 1)
    const a = Math.max(x - 0.001, 0)
    const b = Math.min(x + 0.001, 1)
    const slope = (surface(b) - surface(a)) / (b - a)
    const incident = Math.atan(slope)
    const refracted = Math.asin(Math.sin(incident) / INDEX_OF_REFRACTION)
    const thickness = bezel * (0.25 + surface(x))
    profile[i] = thickness * Math.tan(incident - refracted)
  }
  return profile
}

type DisplacementMap = { url: string; scale: number }
const maps = new Map<string, DisplacementMap>()

function displacementMap(
  width: number,
  height: number,
  radius: number,
  bezel: number,
  magnify: number
): DisplacementMap {
  const key = [width, height, radius, bezel, magnify].join(":")
  const cached = maps.get(key)
  if (cached) return cached

  const profile = rimProfile(bezel)
  const dx = new Float32Array(width * height)
  const dy = new Float32Array(width * height)
  let max = 0

  for (let j = 0; j < height; j++) {
    for (let i = 0; i < width; i++) {
      // signed distance to a rounded rectangle, and the outward normal
      const px = i + 0.5 - width / 2
      const py = j + 0.5 - height / 2
      const qx = Math.abs(px) - width / 2 + radius
      const qy = Math.abs(py) - height / 2 + radius
      const inside =
        -(Math.hypot(Math.max(qx, 0), Math.max(qy, 0)) +
          Math.min(Math.max(qx, qy), 0) -
          radius)
      let nx = 0
      let ny = 0
      if (qx > 0 && qy > 0) {
        const length = Math.hypot(qx, qy) || 1
        nx = (qx / length) * Math.sign(px)
        ny = (qy / length) * Math.sign(py)
      } else if (qx > qy) nx = Math.sign(px)
      else ny = Math.sign(py)

      let x = -px * magnify
      let y = -py * magnify
      if (inside >= 0 && inside < bezel) {
        // sample inward, so the rim shows what's just inside the edge
        const shift = profile[Math.round((inside / bezel) * (SAMPLES - 1))]
        x -= nx * shift
        y -= ny * shift
      }
      const k = j * width + i
      dx[k] = x
      dy[k] = y
      max = Math.max(max, Math.abs(x), Math.abs(y))
    }
  }

  const canvas = document.createElement("canvas")
  canvas.width = width
  canvas.height = height
  const context = canvas.getContext("2d")
  if (!context) return { url: "", scale: 0 }
  const image = context.createImageData(width, height)
  for (let k = 0; k < width * height; k++) {
    // 128 is "no shift"; red moves along x, green along y
    image.data[k * 4] = 128 + (dx[k] / (max || 1)) * 127
    image.data[k * 4 + 1] = 128 + (dy[k] / (max || 1)) * 127
    image.data[k * 4 + 2] = 128
    image.data[k * 4 + 3] = 255
  }
  context.putImageData(image, 0, 0)

  const map = { url: canvas.toDataURL(), scale: max * 2 }
  if (maps.size > 48) maps.delete(maps.keys().next().value!)
  maps.set(key, map)
  return map
}

// only Chromium can use an SVG filter as a backdrop-filter
function canRefract() {
  const nav = navigator as Navigator & {
    userAgentData?: { brands: { brand: string }[] }
  }
  if (nav.userAgentData) {
    return nav.userAgentData.brands.some((b) => b.brand === "Chromium")
  }
  return /Chrome\/\d+/.test(nav.userAgent) && !/Firefox|FxiOS/.test(nav.userAgent)
}

const noopSubscribe = () => () => {}

function useCanRefract() {
  return React.useSyncExternalStore(noopSubscribe, canRefract, () => false)
}

type LiquidGlassProps = React.ComponentProps<"div"> & {
  /** width of the curved rim in px, defaults to the corner radius (max 24) */
  bezel?: number
  /** 0 is flat glass, 1 is the full lens; pass a motion value to animate it */
  refraction?: number | MotionValue<number>
  /** zooms the middle like a magnifier, 0 to 0.3 */
  magnify?: number
  /** blur behind the glass in px */
  frost?: number
  /** a color mixed over the glass, e.g. for a tinted primary button */
  tint?: string
  /**
   * fades the whole pane in and out. Never fade a parent of liquid glass
   * instead: an ancestor with opacity cuts the glass off from what's behind it.
   */
  presence?: number | MotionValue<number>
}

function LiquidGlass({
  bezel,
  refraction = 1,
  magnify = 0,
  frost = 1,
  tint,
  presence = 1,
  className,
  children,
  ...props
}: LiquidGlassProps) {
  const ref = React.useRef<HTMLDivElement>(null)
  const displaceRef = React.useRef<SVGFEDisplacementMapElement>(null)
  const id = `liquid-${React.useId().replace(/[^a-zA-Z0-9_-]/g, "")}`
  const refract = useCanRefract()
  const [shape, setShape] = React.useState<{ w: number; h: number; r: number }>()
  // the scale last written to the filter, so a no-op resize can put it back
  const applied = React.useRef(0)

  React.useEffect(() => {
    const node = ref.current
    if (!node || !refract) return
    const measure = () => {
      const w = Math.round(node.offsetWidth)
      const h = Math.round(node.offsetHeight)
      const raw = getComputedStyle(node).borderTopLeftRadius
      const value = parseFloat(raw) || 0
      const r = Math.round(
        Math.min(raw.endsWith("%") ? (value / 100) * Math.min(w, h) : value, w / 2, h / 2)
      )
      setShape((prev) => {
        if (prev?.w === w && prev.h === h && prev.r === r) {
          displaceRef.current?.setAttribute("scale", String(applied.current))
          return prev
        }
        return { w, h, r }
      })
    }
    // measure right away, then wait for resizing to settle before rebuilding the map
    let first = true
    let frame = 0
    let timer = 0
    const observer = new ResizeObserver(() => {
      if (first) {
        first = false
        measure()
        return
      }
      // until the new map is ready, the old one would bend the wrong pixels
      displaceRef.current?.setAttribute("scale", "0")
      window.clearTimeout(timer)
      timer = window.setTimeout(() => {
        frame = requestAnimationFrame(measure)
      }, 100)
    })
    observer.observe(node)
    return () => {
      observer.disconnect()
      window.clearTimeout(timer)
      cancelAnimationFrame(frame)
    }
  }, [refract])

  const map = React.useMemo(() => {
    if (!refract || !shape || shape.w < 2 || shape.h < 2) return undefined
    const rim = Math.max(1, Math.min(bezel ?? Math.min(shape.r, 24), shape.w / 2, shape.h / 2))
    return displacementMap(shape.w, shape.h, shape.r, Math.round(rim), magnify)
  }, [bezel, magnify, refract, shape])

  // animate refraction by scaling the filter, without rebuilding the map
  React.useEffect(() => {
    if (!map) return
    const apply = (v: number) => {
      applied.current = map.scale * v
      displaceRef.current?.setAttribute("scale", String(applied.current))
    }
    if (typeof refraction === "number") {
      apply(refraction)
      return
    }
    apply(refraction.get())
    return refraction.on("change", apply)
  }, [map, refraction])

  const ownPresence = useMotionValue(isMotionValue(presence) ? 1 : presence)
  const visible = isMotionValue(presence) ? presence : ownPresence
  React.useEffect(() => {
    if (!isMotionValue(presence)) ownPresence.set(presence)
  }, [ownPresence, presence])
  const rimOpacity = useTransform(visible, (v) => v * 0.95)

  const strength = isMotionValue(refraction) ? refraction.get() : refraction
  const backdrop = map
    ? `url(#${id})`
    : `blur(${Math.max(frost, 10)}px) saturate(1.6)`

  return (
    <div
      ref={ref}
      data-slot="liquid-glass"
      // no isolation here: an isolated parent cuts the glass off from the scene
      // behind it in Chrome. Layers stack in source order, and direct children
      // are made relative so they sit on top (wrap an absolute child to keep it).
      className={cn("relative [&>:where(:not([data-glass-layer]))]:relative", className)}
      {...props}
    >
      {map && (
        <svg data-glass-layer aria-hidden width="0" height="0" className="pointer-events-none absolute">
          <filter id={id} colorInterpolationFilters="sRGB">
            <feGaussianBlur in="SourceGraphic" stdDeviation={frost} result="frost" />
            <feImage
              href={map.url}
              x="0"
              y="0"
              width={shape?.w}
              height={shape?.h}
              preserveAspectRatio="none"
              result="map"
            />
            <feDisplacementMap
              ref={displaceRef}
              in="frost"
              in2="map"
              scale={map.scale * strength}
              xChannelSelector="R"
              yChannelSelector="G"
              result="bent"
            />
            {/* glass makes what's behind it a little brighter and more vivid */}
            <feColorMatrix in="bent" type="saturate" values="1.45" result="vivid" />
            <feComponentTransfer in="vivid">
              <feFuncR type="linear" slope="1.05" />
              <feFuncG type="linear" slope="1.05" />
              <feFuncB type="linear" slope="1.05" />
            </feComponentTransfer>
          </filter>
        </svg>
      )}
      <motion.div
        data-glass-layer
        aria-hidden
        className="pointer-events-none absolute inset-0 rounded-[inherit] shadow-[0_10px_30px_-10px_var(--liquid-shadow),0_2px_8px_-2px_var(--liquid-shadow)]"
        style={{ opacity: visible }}
      />
      <motion.div
        data-glass-layer
        aria-hidden
        className="pointer-events-none absolute inset-0 rounded-[inherit]"
        style={{
          backdropFilter: backdrop,
          WebkitBackdropFilter: backdrop,
          opacity: visible,
        }}
      />
      {/* tint, heavier when there's no refraction so text stays legible */}
      <motion.div
        data-glass-layer
        aria-hidden
        className={cn(
          "pointer-events-none absolute inset-0 rounded-[inherit] bg-(--liquid-tint)",
          !map && "bg-(--liquid-fallback)"
        )}
        style={tint ? { background: tint, opacity: visible } : { opacity: visible }}
      />
      {/* volume: light gathers inside the top edge, shade settles along the bottom */}
      <motion.div
        data-glass-layer
        aria-hidden
        className="pointer-events-none absolute inset-0 rounded-[inherit] shadow-[inset_0_1px_16px_-4px_var(--liquid-glow),inset_0_-12px_20px_-14px_var(--liquid-shade)]"
        style={{ opacity: visible }}
      />
      {/* rim light: bright where the light comes from (top left), softer opposite */}
      <motion.div
        data-glass-layer
        aria-hidden
        className="pointer-events-none absolute inset-0 rounded-[inherit] shadow-[inset_0_0_0_0.5px_var(--liquid-edge),inset_1px_1.5px_1px_-1px_var(--liquid-rim),inset_-1px_-1.5px_1px_-1px_color-mix(in_oklch,var(--liquid-rim)_45%,transparent)]"
        style={{ opacity: visible }}
      />
      <motion.div
        data-glass-layer
        aria-hidden
        className="pointer-events-none absolute inset-0 rounded-[inherit] p-px"
        style={{
          ...ringMask,
          background:
            "conic-gradient(from 300deg, var(--liquid-rim), transparent 70deg, transparent 110deg, color-mix(in oklch, var(--liquid-rim) 55%, transparent) 180deg, transparent 250deg, transparent 290deg, var(--liquid-rim))",
          opacity: rimOpacity,
        }}
      />
      {children}
    </div>
  )
}

